import{_ as e,o as l,c as d,a3 as a}from"./chunks/framework.CDCjIvJ8.js";const y=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1789296458000}'),n={name:"reference/environment.md"};function i(o,t,s,r,c,f){return l(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><p>Defined in <code>backend/app/config.py</code> and validated at startup. Full template: <code>backend/.env.example</code>.</p><div class="danger custom-block"><p class="custom-block-title">Never prefix a secret with <code>VITE_</code></p><p>Vite inlines every <code>VITE_</code>-prefixed variable into the shipped browser bundle. A key named that way is public the moment it deploys, and the failure is silent. CI greps the build output for this.</p><p><code>VITE_API_URL</code> is the only frontend variable, and it is meant to be public.</p></div><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to &quot;Application&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ENVIRONMENT</code></td><td style="text-align:left;"><code>production</code></td><td style="text-align:left;"><code>development</code> / <code>staging</code> / <code>production</code></td></tr><tr><td style="text-align:left;"><code>DEBUG</code></td><td style="text-align:left;"><code>False</code></td><td style="text-align:left;">Must be <code>False</code> in production</td></tr><tr><td style="text-align:left;"><code>PORT</code></td><td style="text-align:left;"><code>8000</code></td><td style="text-align:left;">Platform-injected</td></tr><tr><td style="text-align:left;"><code>ALLOWED_ORIGINS</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Comma-separated <strong>exact</strong> origins. <code>*</code> rejected; https required in production</td></tr><tr><td style="text-align:left;"><code>TRUSTED_HOSTS</code></td><td style="text-align:left;"><code>*</code></td><td style="text-align:left;">Must be explicit in production</td></tr><tr><td style="text-align:left;"><code>ENABLE_DOCS</code></td><td style="text-align:left;"><code>False</code></td><td style="text-align:left;">Forced off in production</td></tr><tr><td style="text-align:left;"><code>APP_PUBLIC_URL</code></td><td style="text-align:left;">localhost</td><td style="text-align:left;">Builds invitation links; https in production</td></tr></tbody></table><p>Localhost origins are injected automatically outside production and <strong>never</strong> in production.</p><h2 id="supabase-—-required" tabindex="-1">Supabase — required <a class="header-anchor" href="#supabase-—-required" aria-label="Permalink to &quot;Supabase — required&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SUPABASE_URL</code></td><td style="text-align:left;">Also derives the JWKS URL and expected issuer</td></tr><tr><td style="text-align:left;"><code>SUPABASE_ANON_KEY</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>SUPABASE_SERVICE_ROLE_KEY</code></td><td style="text-align:left;"><strong>Bypasses RLS.</strong> Backend only</td></tr><tr><td style="text-align:left;"><code>SUPABASE_JWT_SECRET</code></td><td style="text-align:left;">Used for legacy HS256 verification</td></tr></tbody></table><h2 id="jwt" tabindex="-1">JWT <a class="header-anchor" href="#jwt" aria-label="Permalink to &quot;JWT&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>JWT_AUDIENCE</code></td><td style="text-align:left;"><code>authenticated</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>JWT_LEEWAY_SECONDS</code></td><td style="text-align:left;"><code>30</code></td><td style="text-align:left;">Clock-skew tolerance</td></tr><tr><td style="text-align:left;"><code>JWKS_CACHE_TTL_SECONDS</code></td><td style="text-align:left;"><code>600</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>JWKS_REFRESH_COOLDOWN_SECONDS</code></td><td style="text-align:left;"><code>30</code></td><td style="text-align:left;">Stops unknown-<code>kid</code> tokens amplifying into one fetch per request</td></tr></tbody></table><h2 id="data-stores-—-required" tabindex="-1">Data stores — required <a class="header-anchor" href="#data-stores-—-required" aria-label="Permalink to &quot;Data stores — required&quot;">​</a></h2><p><code>NEO4J_URI</code>, <code>NEO4J_USERNAME</code>, <code>NEO4J_PASSWORD</code>, <code>NEO4J_DATABASE</code>, <code>QDRANT_URL</code>, <code>QDRANT_API_KEY</code>, <code>QDRANT_COLLECTION_NAME</code>.</p><h2 id="llm-embeddings" tabindex="-1">LLM &amp; embeddings <a class="header-anchor" href="#llm-embeddings" aria-label="Permalink to &quot;LLM &amp; embeddings&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th></tr></thead><tbody><tr><td style="text-align:left;"><code>LLM_PROVIDER</code></td><td style="text-align:left;"><code>groq</code></td></tr><tr><td style="text-align:left;"><code>GROQ_API_KEY</code></td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><code>GROQ_MODEL</code></td><td style="text-align:left;"><code>llama-3.3-70b-versatile</code></td></tr><tr><td style="text-align:left;"><code>EMBEDDING_MODEL</code></td><td style="text-align:left;"><code>BAAI/bge-small-en-v1.5</code></td></tr><tr><td style="text-align:left;"><code>LLM_REQUEST_TIMEOUT_SECONDS</code></td><td style="text-align:left;"><code>45.0</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Changing <code>EMBEDDING_MODEL</code> invalidates the index</p><p>Existing vectors were written in a different space and become meaningless. Changing it requires re-indexing the entire corpus, not just a redeploy.</p></div><h2 id="rate-limiting" tabindex="-1">Rate limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate limiting&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>REDIS_URL</code></td><td style="text-align:left;">localhost</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>REDIS_REQUIRED</code></td><td style="text-align:left;"><code>False</code></td><td style="text-align:left;"><strong>Must be <code>True</code> in production</strong> — otherwise limits fail open</td></tr><tr><td style="text-align:left;"><code>RATE_LIMIT_ENABLED</code></td><td style="text-align:left;"><code>True</code></td><td style="text-align:left;"><strong>Must be <code>True</code> in production</strong></td></tr><tr><td style="text-align:left;"><code>RATE_LIMIT_AUTH_PER_MINUTE</code></td><td style="text-align:left;"><code>5</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>RATE_LIMIT_AUTH_PER_HOUR</code></td><td style="text-align:left;"><code>30</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>RATE_LIMIT_LLM_PER_MINUTE</code></td><td style="text-align:left;"><code>10</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>RATE_LIMIT_LLM_PER_DAY</code></td><td style="text-align:left;"><code>300</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>RATE_LIMIT_UPLOAD_PER_HOUR</code></td><td style="text-align:left;"><code>40</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>RATE_LIMIT_INVITE_PER_HOUR</code></td><td style="text-align:left;"><code>200</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>LLM_TOKEN_BUDGET_PER_DAY</code></td><td style="text-align:left;"><code>150000</code></td><td style="text-align:left;"><code>0</code> disables; request counts alone cannot bound spend</td></tr></tbody></table><h2 id="request-limits" tabindex="-1">Request limits <a class="header-anchor" href="#request-limits" aria-label="Permalink to &quot;Request limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th></tr></thead><tbody><tr><td style="text-align:left;"><code>MAX_REQUEST_BYTES</code></td><td style="text-align:left;">20 MB</td></tr><tr><td style="text-align:left;"><code>MAX_UPLOAD_BYTES</code></td><td style="text-align:left;">15 MB</td></tr><tr><td style="text-align:left;"><code>HSTS_MAX_AGE_SECONDS</code></td><td style="text-align:left;">2 years</td></tr></tbody></table><h2 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>EMAIL_PROVIDER</code></td><td style="text-align:left;"><code>console</code></td><td style="text-align:left;"><code>console</code> prints instead of sending; rejected in production</td></tr><tr><td style="text-align:left;"><code>RESEND_API_KEY</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Required when provider is <code>resend</code></td></tr><tr><td style="text-align:left;"><code>EMAIL_FROM_ADDRESS</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Domain must be verified with the provider</td></tr><tr><td style="text-align:left;"><code>INVITE_TOKEN_TTL_HOURS</code></td><td style="text-align:left;"><code>168</code></td><td style="text-align:left;">7 days</td></tr></tbody></table><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>OTEL_ENABLED</code></td><td style="text-align:left;"><code>False</code></td><td style="text-align:left;">Everything is a no-op when false</td></tr><tr><td style="text-align:left;"><code>OTEL_EXPORTER_OTLP_ENDPOINT</code></td><td style="text-align:left;">—</td><td style="text-align:left;">e.g. <code>http://localhost:4318</code></td></tr><tr><td style="text-align:left;"><code>OTEL_EXPORTER_OTLP_HEADERS</code></td><td style="text-align:left;">—</td><td style="text-align:left;"><code>key=value,key2=value2</code></td></tr><tr><td style="text-align:left;"><code>OTEL_TRACES_SAMPLER_RATIO</code></td><td style="text-align:left;"><code>1.0</code></td><td style="text-align:left;">0.25 in production</td></tr><tr><td style="text-align:left;"><code>LOG_FORMAT</code></td><td style="text-align:left;"><code>console</code></td><td style="text-align:left;">Use <code>json</code> in deployed environments</td></tr><tr><td style="text-align:left;"><code>LOG_LEVEL</code></td><td style="text-align:left;"><code>INFO</code></td><td style="text-align:left;"></td></tr></tbody></table><h2 id="production-invariants" tabindex="-1">Production invariants <a class="header-anchor" href="#production-invariants" aria-label="Permalink to &quot;Production invariants&quot;">​</a></h2><p>Startup fails unless all hold:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DEBUG                = False</span></span>
<span class="line"><span>ALLOWED_ORIGINS      ⊇ one https origin, no &quot;*&quot;</span></span>
<span class="line"><span>TRUSTED_HOSTS        ≠ &quot;*&quot;</span></span>
<span class="line"><span>RATE_LIMIT_ENABLED   = True</span></span>
<span class="line"><span>REDIS_REQUIRED       = True</span></span>
<span class="line"><span>EMAIL_PROVIDER       ≠ &quot;console&quot;</span></span>
<span class="line"><span>RESEND_API_KEY       set when provider is resend</span></span>
<span class="line"><span>APP_PUBLIC_URL       starts with https://</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Failing to start is deliberate. A production deployment silently running with rate limiting disabled or wildcard CORS is worse than one that refuses to boot and says why.</p>`,27)])])}const x=e(n,[["render",i]]);export{y as __pageData,x as default};
